"""Reproduce public Go wire models and test both real API schemas.

--check compares generated bytes without modifying committed output.
--core additionally compiles both complete schemas and runs wire contract probes.
No schema is downgraded; private schema artifacts stay under ignored build/.
"""

from pathlib import Path
from prepare_go_schema import prepare
import argparse
import hashlib
import json
import os
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[1]


def generate(go: str, source: Path, destination: Path, package: str) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    prepared = destination.parent / "prepared.json"
    prepared.write_text(json.dumps(prepare(json.loads(source.read_text())), sort_keys=True, indent=2) + "\n")
    config = destination.parent / "generator.json"
    settings = json.loads((ROOT / "api/oapi-codegen.json").read_text())
    settings.update(package=package, output=str(destination))
    config.write_text(json.dumps(settings, indent=2) + "\n")
    subprocess.run(
        [go, "tool", "-modfile=tools/go.mod", "oapi-codegen", "-config", str(config), str(prepared)],
        cwd=ROOT,
        check=True,
        timeout=120,
    )


def union_test(type_name: str, payloads: list[str]) -> str:
    literals = ",".join(json.dumps(p) for p in payloads)
    return f"""package schemagate
import ("encoding/json"; "testing"; "bytes")
func TestUnionRoundTrip(t *testing.T){{
 for _,raw:=range []string{{{literals}}}{{
  var value {type_name}
  if err:=json.Unmarshal([]byte(raw),&value);err!=nil{{t.Fatal(err)}}
  encoded,err:=json.Marshal(value);if err!=nil{{t.Fatal(err)}}
  var compact bytes.Buffer
  if err:=json.Compact(&compact,encoded);err!=nil{{t.Fatal(err)}}
  if compact.String()!=raw{{t.Fatalf("union changed: %s -> %s",raw,encoded)}}
 }}
}}
"""


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--go", default=os.environ.get("GO", "go"))
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--core", type=Path)
    args = parser.parse_args()
    build = ROOT / "build/go"
    build.mkdir(parents=True, exist_ok=True)
    target = ROOT / "client/wire/types.gen.go"
    with tempfile.TemporaryDirectory(prefix="wire-", dir=build) as temporary:
        generated = Path(temporary) / "types.gen.go"
        generate(args.go, ROOT / "api/public.json", generated, "wire")
        if args.check:
            if generated.read_bytes() != target.read_bytes():
                raise SystemExit("Go wire models are stale: run make go-generate")
        else:
            target.write_bytes(generated.read_bytes())
    if args.core:
        report = {}
        for kind in ("public", "internal"):
            source = args.core.resolve() / f"control/openapi/{kind}.json"
            # Separate configurations are mandatory: oapi-codegen's configured
            # output takes precedence over its -o flag.
            destination = build / f"full-schema-gate/{kind}/types.gen.go"
            generate(args.go, source, destination, "schemagate")
            union = "GitHubWorkflow_State" if kind == "public" else "AdminSettingUpdate_Value"
            payloads = ['"active"', '"future_state"'] if kind == "public" else ["true", '"auto"', "42", '["one","two"]']
            (destination.parent / "union_test.go").write_text(union_test(union, payloads))
            if kind == "public":
                contracts = (
                    (ROOT / "client/wire/types_test.go").read_text().replace("package wire", "package schemagate", 1)
                )
                (destination.parent / "contracts_test.go").write_text(contracts)
            subprocess.run(
                [args.go, "test", "./" + str(destination.parent.relative_to(ROOT))],
                cwd=ROOT,
                check=True,
                timeout=120,
            )
            report[kind] = {"sha256": hashlib.sha256(source.read_bytes()).hexdigest(), "passed": True}
        (build / "schema-gate.json").write_text(json.dumps(report, indent=2) + "\n")
    print("Go schema generation checks passed.")


if __name__ == "__main__":
    main()
